function main({ urls, draftData }) {
  const imgUrls = [], docUrls = [], issues = [], manifest = [];
  const seen = new Set();
  for (const raw of Array.isArray(urls) ? urls : []) {
    if (typeof raw !== 'string' || !/^https?:\/\//i.test(raw)) {
      issues.push('存在无效文件链接，请通过文件上传入口重新上传。'); continue;
    }
    if (seen.has(raw)) continue;
    seen.add(raw);
    let path = raw.split(/[?#]/)[0];
    try { path = decodeURIComponent(path); } catch (_) {}
    const ext = (path.match(/\.([a-z0-9]+)$/i) || [,''])[1].toLowerCase();
    const source = 'F' + (manifest.length + 1);
    if (['jpg','jpeg','png','webp','bmp','tif','tiff'].includes(ext)) {
      imgUrls.push(raw); manifest.push({ source, type: 'image', index: imgUrls.length });
    } else if (['pdf','html','htm'].includes(ext)) {
      docUrls.push(raw); manifest.push({ source, type: ext === 'pdf' ? 'pdf' : 'html', index: docUrls.length });
    } else {
      manifest.push({ source, type: 'unsupported', index: 0 });
      issues.push(source + '无法根据链接确认是图片、PDF或HTML；请重新上传带正确扩展名的文件。');
    }
  }
  if (seen.size > 8) issues.push('本次文件超过8个，请减少数量后重试，不会截断处理。');
  const rawHtml = typeof draftData === 'string' ? draftData.trim() : '';
  if (!seen.size && !rawHtml) issues.push('请上传同一病例的图片、PDF或HTML，或填写draftData正文。');
  return { imgUrls, docUrls, rawHtml, manifest: JSON.stringify(manifest), routeIssues: JSON.stringify(issues) };
}

function main({ imgUrls, docText, rawHtml, routeIssues, docUrls, docError }) {
  const issues = [];
  try { issues.push(...JSON.parse(routeIssues || '[]')); } catch (_) { issues.push('文件分流状态无法解析。'); }
  const text = typeof docText === 'string' ? docText : '';
  const html = typeof rawHtml === 'string' ? rawHtml : '';
  if (Array.isArray(docUrls) && docUrls.length && !text.trim()) issues.push('文档未提取出文字；扫描PDF请检查PDF增强解析服务，或将页面作为图片上传。');
  if (docError) issues.push('文档解析节点报错，请检查运行记录后重试。');
  const images = Array.isArray(imgUrls) ? [...imgUrls] : [];
  const labels = images.map((_, i) => '上传图片' + (i + 1));
  // Remove executable/non-content blocks before inspecting inline image references.
  const combined = (text + '\n' + html).replace(/<(script|style|noscript)\b[^>]*>[\s\S]*?<\/\1>/gi, '');
  let unresolved = 0;
  const candidates = [];
  for (const m of combined.matchAll(/<img\b[^>]*?\bsrc\s*=\s*["']([^"']+)["'][^>]*>/gi)) candidates.push(m[1]);
  for (const m of combined.matchAll(/!\[[^\]]*\]\(\s*(?:<([^>]+)>|([^\s)]+))(?:\s+["'][^)]*)?\s*\)/g)) candidates.push(m[1] || m[2]);
  for (let u of candidates) {
    u = u.replace(/&amp;/g, '&');
    if (!/^https?:\/\//i.test(u)) { unresolved++; continue; }
    if (!images.includes(u)) { images.push(u); labels.push('文档内嵌图片' + (labels.filter(x => x.startsWith('文档')).length + 1)); }
  }
  if (unresolved) issues.push('有' + unresolved + '个内嵌图片引用不是绝对HTTP链接，未识别；请将相关报告图片单独上传。');
  if (images.length > 24) issues.push('图片总数超过24，已停止OCR以免部分识别；请拆分无关资料或删除装饰图片后重试。');
  // Conservative identity-label masking. Full de-identification remains model + human review.
  function clean(s) {
    return s.replace(/<(script|style|noscript)\b[^>]*>[\s\S]*?<\/\1>/gi, '')
      .replace(/<\/?(?:p|div|br|tr|li|h[1-6])\b[^>]*>/gi, '\n')
      .replace(/<!--[\s\S]*?-->/g, '').replace(/<\/?[a-z][^>]*>/gi, ' ').replace(/!\[[^\]]*\]\([^)]*\)/g, '[图片另行OCR]')
      .replace(/&nbsp;/g, ' ').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&amp;/g, '&')
      .replace(/(?:姓名|患者姓名|住院号|门诊号|身份证号|联系电话|家庭住址)\s*[:：]\s*[^\s，,；;]+/g, '[身份信息已遮蔽]')
      .replace(/https?:\/\/[^\s<>"']+/g, '[来源链接隐藏]')
      .replace(/\n[ \t]*\n(?:[ \t]*\n)+/g, '\n\n').trim();
  }
  const textBlocks = [];
  if (text.trim()) textBlocks.push({source:'文档解析汇总（逐文件及页码以正文实际标记为准）', text:clean(text)});
  if (html.trim()) textBlocks.push({source:'draftData正文', text:clean(html)});
  return { ocrUrls: images.length <= 24 ? images : [], imageLabels: JSON.stringify(labels), textBlocks: JSON.stringify(textBlocks), issues: JSON.stringify(issues), expectedImages: images.length };
}

function main({ texts, imageLabels, textBlocks, issues, expectedImages, ocrError }) {
  const parse = (v, fallback) => { try { return JSON.parse(v); } catch (_) { return fallback; } };
  const problems = parse(issues || '[]', ['预处理状态损坏。']);
  const blocks = parse(textBlocks || '[]', []);
  const labels = parse(imageLabels || '[]', []);
  const arr = Array.isArray(texts) ? texts : [];
  if (ocrError) problems.push('图片OCR节点报错，请检查运行记录后重试。');
  if (expectedImages > 0 && arr.length !== expectedImages) problems.push('OCR返回条数与图片数不一致，不能确认资料完整。');
  arr.forEach((t, i) => {
    if (typeof t !== 'string' || !t.trim()) { problems.push('图片' + (i+1) + '未识别出文字。'); return; }
    const masked = t.replace(/(?:姓名|患者姓名|住院号|门诊号|身份证号|联系电话|家庭住址)\s*[:：]\s*[^\s，,；;]+/g, '[身份信息已遮蔽]')
      .replace(/https?:\/\/[^\s<>"']+/g, '[来源链接隐藏]');
    blocks.push({source:labels[i] || 'OCR图片' + (i+1),text:masked});
  });
  const sourceText = JSON.stringify({materials:blocks});
  if (!blocks.some(b => b.text && b.text.trim())) problems.push('没有可用病例正文。');
  if (sourceText.length > 65000) problems.push('正文超过65000字符，未截断；请减少无关内容后重新提交。');
  return { sourceText, issues:JSON.stringify([...new Set(problems)]), ready: problems.length === 0 ? 'true' : 'false' };
}

